B.ahi=new A.bW(B.dy,["\u0996\u09be\u09ac\u09be\u09b0","\u0996\u09be\u09ac\u09be\u09b0 \u09b6\u09c7\u09b7\u09c7\u09b0 \u09a6\u09cb\u09af\u09bc\u09be","After eating","\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u0623\u064e\u0637\u0652\u0639\u064e\u0645\u064e\u0646\u064e\u0627 \u0648\u064e\u0633\u064e\u0642\u064e\u0627\u0646\u064e\u0627 \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u064e\u0646\u064e\u0627 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e","\u09b8\u0995\u09b2 \u09aa\u09cd\u09b0\u09b6\u0982\u09b8\u09be \u0986\u09b2\u09cd\u09b2\u09be\u09b9\u09b0, \u09af\u09bf\u09a8\u09bf \u0986\u09ae\u09be\u09a6\u09c7\u09b0 \u0996\u09be\u0993\u09af\u09bc\u09be\u09b2\u09c7\u09a8, \u09aa\u09be\u09a8 \u0995\u09b0\u09be\u09b2\u09c7\u09a8 \u098f\u09ac\u0982 \u09ae\u09c1\u09b8\u09b2\u09bf\u09ae \u09ac\u09be\u09a8\u09be\u09b2\u09c7\u09a8\u0964","All praise is for Allah who fed us, gave us drink and made us Muslims.",2],t.yf)
B.ahd=new A.bW(B.dy,["\u09b0\u09ae\u09be\u09a6\u09be\u09a8","\u0987\u09ab\u09a4\u09be\u09b0\u09c7\u09b0 \u09a6\u09cb\u09af\u09bc\u09be","Breaking the fast","\u0630\u064e\u0647\u064e\u0628\u064e \u0627\u0644\u0638\u064e\u0651\u0645\u064e\u0623\u064f \u0648\u064e\u0627\u0628\u0652\u062a\u064e\u0644\u064e\u0651\u062a\u0650 \u0627\u0644\u0652\u0639\u064f\u0631\u064f\u0648\u0642\u064f \u0648\u064e\u062b\u064e\u0628\u064e\u062a\u064e \u0627\u0644\u0623\u064e\u062c\u0652\u0631\u064f \u0625\u0650\u0646\u0652 \u0634\u064e\u0627\u0621\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f","\u09aa\u09bf\u09aa\u09be\u09b8\u09be \u09a6\u09c2\u09b0 \u09b9\u09b2\u09cb, \u09b6\u09bf\u09b0\u09be-\u0989\u09aa\u09b6\u09bf\u09b0\u09be \u09b8\u09a4\u09c7\u099c \u09b9\u09b2\u09cb \u098f\u09ac\u0982 \u0987\u09a8\u09b6\u09be\u0986\u09b2\u09cd\u09b2\u09be\u09b9 \u09aa\u09cd\u09b0\u09a4\u09bf\u09a6\u09be\u09a8 \u09a8\u09bf\u09b6\u09cd\u099a\u09bf\u09a4 \u09b9\u09b2\u09cb\u0964","The thirst is gone, the veins are moist and the reward is confirmed, if Allah wills.",3],t.yf)
B.ahe=new A.bW(B.dy,["\u09b0\u09ae\u09be\u09a6\u09be\u09a8","\u09b2\u09be\u0987\u09b2\u09be\u09a4\u09c1\u09b2 \u0995\u09a6\u09b0\u09c7\u09b0 \u09a6\u09cb\u09af\u09bc\u09be","Night of Power",u.d3,"\u09b9\u09c7 \u0986\u09b2\u09cd\u09b2\u09be\u09b9, \u0986\u09aa\u09a8\u09bf \u0995\u09cd\u09b7\u09ae\u09be\u09b6\u09c0\u09b2, \u0995\u09cd\u09b7\u09ae\u09be \u0995\u09b0\u09a4\u09c7 \u09ad\u09be\u09b2\u09cb\u09ac\u09be\u09b8\u09c7\u09a8; \u0985\u09a4\u098f\u09ac \u0986\u09ae\u09be\u0995\u09c7 \u0995\u09cd\u09b7\u09ae\u09be \u0995\u09b0\u09c1\u09a8\u0964","O Allah, You are Forgiving and love forgiveness, so forgive me.",4],t.yf)
B.ahl=new A.bW(B.dy,["\u09a6\u09c8\u09a8\u09a8\u09cd\u09a6\u09bf\u09a8","\u0998\u09c1\u09ae\u09be\u09a8\u09cb\u09b0 \u09a6\u09cb\u09af\u09bc\u09be","Before sleeping","\u0628\u0650\u0627\u0633\u0652\u0645\u0650\u0643\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f\u0645\u064e\u0651 \u0623\u064e\u0645\u064f\u0648\u062a\u064f \u0648\u064e\u0623\u064e\u062d\u0652\u064a\u064e\u0627","\u09b9\u09c7 \u0986\u09b2\u09cd\u09b2\u09be\u09b9, \u0986\u09aa\u09a8\u09be\u09b0 \u09a8\u09be\u09ae\u09c7\u0987 \u09ae\u09b0\u09bf \u098f\u09ac\u0982 \u09ac\u09be\u0981\u099a\u09bf\u0964","In Your name, O Allah, I die and I live.",5],t.yf)
B.ahk=new A.bW(B.dy,["\u09a6\u09c8\u09a8\u09a8\u09cd\u09a6\u09bf\u09a8","\u0998\u09c1\u09ae \u09a5\u09c7\u0995\u09c7 \u0993\u09a0\u09be\u09b0 \u09a6\u09cb\u09af\u09bc\u09be","Upon waking","\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u0623\u064e\u062d\u0652\u064a\u064e\u0627\u0646\u064e\u0627 \u0628\u064e\u0639\u0652\u062f\u064e \u0645\u064e\u0627 \u0623\u064e\u0645\u064e\u0627\u062a\u064e\u0646\u064e\u0627 \u0648\u064e\u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0646\u064f\u0651\u0634\u064f\u0648\u0631\u064f","\u09b8\u0995\u09b2 \u09aa\u09cd\u09b0\u09b6\u0982\u09b8\u09be \u0986\u09b2\u09cd\u09b2\u09be\u09b9\u09b0, \u09af\u09bf\u09a8\u09bf \u09ae\u09c3\u09a4\u09cd\u09af\u09c1\u09b0 \u09aa\u09b0 \u0986\u09ae\u09be\u09a6\u09c7\u09b0 \u099c\u09c0\u09ac\u09a8 \u09a6\u09bf\u09b2\u09c7\u09a8 \u098f\u09ac\u0982 \u09a4\u09be\u0981\u09b0 \u0995\u09be\u099b\u09c7\u0987 \u09ab\u09bf\u09b0\u09c7 \u09af\u09c7\u09a4\u09c7 \u09b9\u09ac\u09c7\u0964","All praise is for Allah who gave us life after death, and to Him is the resurrection.",6],t.yf)
